        {
          "id": "j9dh1NETaVqYUZMi",
          "name": "Destructive Interference",
          "kind": "reaction",
          "description": "Trigger A foe within 90 feet uses an auditory or sonic effect\nEffect The young wailing dragon releases a burst of noise, attempting to drown out the triggering sound. It makes a counteract check against the effect (counteract rank 3, counteract modifier 1d20+16).",
          "traits": [
            "arcane",
            "auditory"
          ]
        },
        {
          "id": "mNiOCK4JOxGwe3HP",
          "name": "Subsonic Drone",
          "kind": "passive",
          "description": "90 feet. A creature who enters or begins their turn in the area must attempt a check (fortitude, dc:21, options:area-effect,inflicts:sickened) save. Regardless of the result of the saving throw, the creature is temporarily immune to this dragon's subsonic drone for 1 minute.\nCritical Success The creature is unaffected.\nSuccess The creature is Sickened 1.\nFailure The creature is Sickened 2.\nCritical Failure The creature is Sickened 3.",
          "traits": [
            "auditory",
            "aura"
          ]
        },
        {
          "id": "TGb0opYaR25KuoIG",
          "name": "Eerie Call",
          "kind": "action",
          "description": "Requirements The dragon is Hidden or undetected\nEffect The dragon's wail draws in unsuspecting opponents. Anyone that can hear the Eerie Call must attempt a check (will, dc:24) save or become Fascinated by the sound. A fascinated creature must spend at least 1 action Seeking the dragon each turn, and the dragon can Sustain this affect for up to 1 minute",
          "traits": [
            "arcane",
            "auditory",
            "emotion",
            "fear",
            "mental"
          ]
        },
        {
          "id": "5G8y4CT30MCjFbMr",
          "name": "Natural Mimic",
          "kind": "passive",
          "description": "The dragon can imitate any sound or voice that it has heard. This has the effect of 2nd-rank Ventriloquism (DC 24) but is a nonmagical effect.",
          "traits": []
        },
        {
          "id": "oFyE8V3tW6qITvhC",
          "name": "Resounding Roar",
          "kind": "action",
          "description": "The dragon unleashes a thunderous call that deals 7d6 sonic damage in a 30-foot type:cone (check (fortitude, dc:24, basic) save). On a critical failure, a creature is also Deafened for 1 minute. The dragon can't use Resounding Roar again for 1d4.",
          "traits": [
            "arcane",
            "sonic"
          ]
        }
