    "sourceHash": "sha256:14fbeceaccef31a4ab3f051f94851ff6051a96cdd5544814571a52d2965bf3fe",
    "translatableHash": "sha256:2b676aa618d43a5a651b74592648c206d7fab0026dfaadc63218ebeabc9a9aeb",
    "data": {
      "schemaVersion": 1,
      "name": "Wailing Dragon (Adult)",
      "level": 10,
      "rarity": "common",
      "size": "huge",
      "traits": [
        "arcane",
        "dragon"
      ],
      "description": "Canny, patient, and creative, wailing dragons are adepts of sound and psychology. With both their physiology and innate connection to arcane magic allowing them to produce and shape sound waves, these reclusive creatures are heard much more often than seen. Named for their tendency to use uncanny keening vocalizations to communicate across long distances and startle prey, wailing dragons haunt locations that create interesting or useful echoes, such as canyons or caverns. Though ruthless predators when needed, most wailing dragons devote their energy toward investigating the effects sound has on the environment and the bodies and minds of creatures.\nMinstrels, divas, and tunesmiths seek out these creatures during their mating season, when two dragons sing courtship ballads full of intricate harmonies. While this might be the performance of a lifetime, it's a dangerous concert, as incautious audience members frequently become meals for the nuptial couple. (The famous Chelaxian composer, Gretezi Valtros, disappeared on such an expedition in 4275 ar, after he set out to teach a wailing dragon High Azlanti and \"instruct it in the decorous art of opera.\") Most creatures also find the close-range subsonic vibrations emitted by wailing dragons extremely uncomfortable, reinforcing the idea that it's best to observe them from a distance.",
      "armorClass": 29,
      "hitPoints": 215,
      "speedFeet": 35,
      "perception": {
        "modifier": 22,
        "senses": [
          "darkvision",
          "echolocation-120"
        ]
      },
      "saves": {
        "fortitude": 19,
        "reflex": 22,
        "will": 17
      },
      "abilities": {
        "str": 7,
        "dex": 5,
        "con": 3,
        "int": 0,
        "wis": 3,
        "cha": 5
      },
      "skills": {
        "acrobatics": 19,
        "athletics": 21,
        "crafting": 17,
        "intimidation": 19,
        "nature": 17,
        "performance": 22,
        "stealth": 19
      },
      "languages": [
        "common",
        "draconic"
      ],
      "defenses": {
        "immunities": [
          "deafened",
          "paralyzed",
          "sleep"
        ],
        "resistances": [
          "sonic 15"
        ],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "iXGIcLA4oV1Dr9lO",
          "name": "Jaws",
          "bonus": 21,
          "damage": "2d10+11 piercing",
          "traits": [
            "magical",
            "reach-15"
          ]
        },
        {
          "id": "rD75dxutGZr275NO",
          "name": "Claw",
          "bonus": 21,
          "damage": "2d6+11 slashing",
          "traits": [
            "agile",
            "magical",
            "reach-10"
          ]
        },
        {
          "id": "vWgDLuno1djYCVuD",
          "name": "Tail",
          "bonus": 19,
          "damage": "2d12+11 bludgeoning",
          "traits": [
            "magical",
            "reach-20"
          ]
        },
        {
          "id": "nv6lzrAojscMc0MG",
          "name": "Shriek",
          "bonus": 19,
          "damage": "2d6+4 sonic",
          "traits": [
            "magical",
            "sonic"
          ]
        }
      ],
      "actions": [
        {
          "id": "OWtwTkenaM8ZtmFV",
          "name": "Echolocation",
          "kind": "passive",
          "description": "A wailing dragon can use its hearing as a precise sense at the listed range.",
          "traits": []
        },
        {
          "id": "xGhzYsT7nrPdNe1Q",
          "name": "+2 Status to All Saves vs. Auditory and Sonic",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "j9dh1NETaVqYUZMi",
          "name": "Destructive Interference",
          "kind": "reaction",
          "description": "Trigger A foe within 90 feet uses an auditory or sonic effect\nEffect The adult wailing dragon releases a burst of noise, attempting to drown out the triggering sound. It makes a counteract check against the effect (counteract rank 5, counteract modifier 1d20+21).",
          "traits": [
            "arcane",
            "auditory"
          ]
        },
        {
          "id": "mNiOCK4JOxGwe3HP",
          "name": "Subsonic Drone",
          "kind": "passive",
          "description": "90 feet. A creature who enters or begins their turn in the area must attempt a check (fortitude, dc:26, options:area-effect,inflicts:sickened) save. Regardless of the result of the saving throw, the creature is temporarily immune to this dragon's subsonic drone for 1 minute.\nCritical Success The creature is unaffected.\nSuccess The creature is Sickened 1.\nFailure The creature is Sickened 2.\nCritical Failure The creature is Sickened 3.",
          "traits": [
            "auditory",
            "aura"
          ]
        },
        {
          "id": "c7YIwyvzHzpG4cua",
          "name": "Draconic Frenzy",
          "kind": "action",
          "description": "The dragon makes two claw Strikes and one tail Strike in any order.",
          "traits": []
        },
        {
          "id": "hlrGExdpJovsAPHP",
          "name": "Draconic Momentum",
          "kind": "passive",
          "description": "The dragon recharges their Resounding Roar whenever they score a critical hit with a Strike.",
          "traits": []
        },
        {
          "id": "TGb0opYaR25KuoIG",
          "name": "Eerie Call",
          "kind": "action",
          "description": "Requirements The dragon is Hidden or undetected\nEffect The dragon's wail draws in unsuspecting opponents. Anyone that can hear the Eerie Call must attempt a check (will, dc:29) save or become Fascinated by the sound. A fascinated creature must spend at least 1 action Seeking the dragon each turn, and the dragon can Sustain this affect for up to 1 minute",
          "traits": [
            "arcane",
            "auditory",
            "emotion",
            "fear",
            "mental"
          ]
        },
        {
          "id": "5G8y4CT30MCjFbMr",
          "name": "Natural Mimic",
          "kind": "passive",
          "description": "The dragon can imitate any sound or voice that it has heard. This has the effect of 2nd-rank Ventriloquism (DC 29) but is a nonmagical effect.",
          "traits": []
        },
        {
          "id": "oFyE8V3tW6qITvhC",
          "name": "Resounding Roar",
          "kind": "action",
          "description": "The dragon unleashes a thunderous call that deals 11d6 sonic damage in a 60-foot type:cone (check (fortitude, dc:29, basic) save). On a critical failure, a creature is also Deafened for 1 minute.\nIn addition, if the area overlaps with an area of magical silence or includes a creature affected by magical silence, the roar attempts to counteract the silence effect (counteract rank 5, counteract modifier 1d20+21).\nThe dragon can't use Resounding Roar again for 1d4.",
          "traits": [
            "arcane",
            "sonic"
          ]
        }
      ],
      "spellcasting": [
        {
          "id": "Dnu45pj9tBRQVdVg",
          "name": "Arcane Innate Spells",
          "tradition": "arcane",
          "category": "innate",
          "attackModifier": 0,
          "saveDc": 27,
          "spells": [
            {
              "id": "rS7b7t7WoKOTBpEc",
              "name": "Figment (auditory only)",
              "rank": 1
            },
            {
              "id": "EdXxC1phdsY0RWIf",
              "name": "Message",
              "rank": 1
            },
            {
              "id": "vvtWynPBbBqKpdu5",
              "name": "Noise Blast (at will)",
              "rank": 5
            },
            {
              "id": "WPYPNqDT3iTAdSAd",
              "name": "Shatter",
              "rank": 5
            }
          ]
        }
      ]
    }
