        {
          "id": "CMNW1v0OIyvhzPLA",
          "name": "Bathygenic Barrage",
          "kind": "action",
          "description": "Frequency once per day\nEffect The dragon uses Pressurized Pool three times. None of the bursts can overlap.",
          "traits": [
            "primal"
          ]
        },
        {
          "id": "CAz0y1bHeuUkucO1",
          "name": "Benthic Bite",
          "kind": "passive",
          "description": "A creature who takes damage from a brine dragon's jaws Strike must succeed at a check (fortitude, dc:29, options:inflicts:enfeebled) save or be Enfeebled 2 for 1 round.",
          "traits": [
            "primal"
          ]
        },
        {
          "id": "rCCO1uInouBztVoX",
          "name": "Crushing Breath",
          "kind": "action",
          "description": "The dragon spews a 80-foot type:line of pressurized water that deals 13d6 bludgeoning damage with a check (reflex, dc:32, basic, options:area-effect,inflicts:clumsy) save. A creature that fails the save is also Clumsy 1 (Clumsy 2 on a critical failure) for 1 minute. The dragon can't use Crushing Breath again for 1d4.",
          "traits": [
            "primal"
          ]
        },
        {
          "id": "nWEiNzJVO4NSKZA8",
          "name": "Pressurized Pool",
          "kind": "action",
          "description": "The dragon expels a 10-foot type:burst of pressurized water within 120 feet that lasts for 1 minute. A creature other than a brine dragon that enters or begins their turn within a burst must succeed at a check (fortitude, dc:32, options:area-effect,inflicts:encumbered) save or become Encumbered until the beginning of their next turn.",
          "traits": [
            "primal"
          ]
        },
        {
          "id": "oiW2Z0YQvzSur4Yk",
          "name": "Tidal Surge",
          "kind": "action",
          "description": "The dragon sweeps their wings, creating a 30-foot type:cone of buffeting water that deals 8d8 bludgeoning damage with a check (fortitude, dc:32, basic, options:area-effect,forced-movement,inflicts:prone) save. Each unattended object and each creature that fails the save is also pushed away from the dragon 10 feet (20 feet on a critical failure) and is knocked Prone. The dragon can't use Tidal Surge again for 1d4.",
          "traits": [
            "primal"
          ]
        }
