      "actions": [
        {
          "id": "bk1emWE3O2UjqdfH",
          "name": "Mist Vision",
          "kind": "passive",
          "description": "Fog and mist don't impair a sky dragon's vision; they ignore the Concealed condition from fog and mist.",
          "traits": []
        },
        {
          "id": "4VxBezFWy6395TrE",
          "name": "+1 Status to All Saves vs. Magic",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "3Rvv7113GcjVIapv",
          "name": "Countered by Fire",
          "kind": "passive",
          "description": "If the sky dragon takes fire damage, the elemental magic of metal within them is tempered. Until the end of their next turn, they take a –1 circumstance penalty to attack rolls and AC, and their jaws Strikes don't deal electricity damage. This limitation ends if the dragon uses Steel Lightning Breath.\nEffect: Countered by Fire",
          "traits": []
        },
        {
          "id": "AFVAfNllPP57qXbc",
          "name": "Fed by Earth",
          "kind": "passive",
          "description": "When a sky dragon is targeted by an earth spell or effect, they crystallize the minerals in their scales to create a light-bending or light-scattering layer for camouflage. For 1 minute, the dragon is Concealed while flying.",
          "traits": [
            "divine"
          ]
        },
        {
          "id": "cFCW9QctlOAAjdbZ",
          "name": "Frightful Presence",
          "kind": "passive",
          "description": "90 feet. check (will, dc:38, options:area-effect,inflicts:frightened)",
          "traits": [
            "aura",
            "emotion",
            "fear",
            "mental"
          ]
        },
        {
          "id": "aHXJdwChpmPAMjUL",
          "name": "Coiling Frenzy",
          "kind": "action",
          "description": "The dragon makes one claw Strike and one tail Strike in either order, each against the same target. If either Strike hits, the dragon can attempt to Grab the target with that limb as a free action. The dragon can have up to three creatures Grabbed or Restrained at a time; one in each of its front claws, and a last with their tail.",
          "traits": []
        },
        {
          "id": "6fbgWORhcpA2p5tO",
          "name": "Divine Lightning",
          "kind": "passive",
          "description": "Requirements The dragon worships a deity whose sanctification entry lists \"holy\"\nEffect The sky dragon channels divine power through its attacks, making them more effective against the unholy. Any electricity damage it deals becomes spirit damage against unholy creatures.",
          "traits": [
            "divine",
            "holy"
          ]
        },
        {
          "id": "kIwvZAdsmvMlX5Y0",
          "name": "Draconic Momentum",
          "kind": "passive",
          "description": "The dragon recharges Steel Lightning Breath whenever they score a critical hit with a Strike.",
          "traits": []
        },
        {
          "id": "k337zC5VCsmhbySb",
          "name": "Greater Constrict",
          "kind": "action",
          "description": "3d10+8 bludgeoning damage, check (fortitude, dc:40, basic, options:inflicts:unconscious)",
          "traits": []
        },
        {
          "id": "wHguWIp8TVV0D1cX",
          "name": "Perfected Flight",
          "kind": "passive",
          "description": "A sky dragon can hover in place without spending an action, and they automatically succeed at all Acrobatics checks to Maneuver in Flight.",
          "traits": []
        },
        {
          "id": "gvL4Ckw5HBylf6Fw",
          "name": "Steel Lightning Breath",
          "kind": "action",
          "description": "The dragon shoots a ball of electricity that deals 10d12 electricity damage in a 30-foot burst within 60 feet (check (reflex, dc:40, basic, options:area-effect) save). They can't use Steel Lightning Breath again for 1d4.",
          "traits": [
            "divine",
            "electricity"
          ]
        },
        {
          "id": "VveOgUlByJLSUYjZ",
          "name": "Stunning Electricity",
          "kind": "action",
          "description": "The dragon rapidly coils, then unleashes crackling lightning that deals 5d12 electricity damage in a 60-foot emanation. Each creature in the area must attempt a check (fortitude, dc:40, options:area-effect,damaging-effect,inflicts:stunned) save; regardless of the outcome, the creature then becomes temporarily immune for 10 minutes.\nCritical Success The creature is unaffected.\nSuccess The creature takes half damage and is Stunned 1.\nFailure The creature takes full damage, is stunned for 1 round, and can't fly for 4 rounds.\nCritical Failure The creature takes double damage, is stunned for 2 rounds, and can't fly for 1 minute.",
          "traits": [
            "divine",
            "electricity",
            "incapacitation"
          ]
        }
      ],
