      "actions": [
        {
          "id": "zkcQGrvQXeO0d4YV",
          "name": "+2 to Sense Motive",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "TFKVhj0omMVlDTbf",
          "name": "Communal Knowledge",
          "kind": "action",
          "description": "The dragon mentally communes with all their current active informants simultaneously. They learn the present state of all the informants, as status, and any new information the informants have learned since they were last in communication. Fragments of extraneous information briefly remain after using Communal Knowledge; for the next hour, the dragon can attempt Recall Knowledge checks for any skill with a modifier of +36.",
          "traits": [
            "concentrate",
            "occult",
            "scrying"
          ]
        },
        {
          "id": "eyJ8okEtlxlLWhjy",
          "name": "Information Network",
          "kind": "passive",
          "description": "The dragon can attempt a Society check to Recall Knowledge in place of a check to Gather Information, recalling intelligence from prior informants.",
          "traits": []
        },
        {
          "id": "o5snVqE0HFhxfgMS",
          "name": "Constant Spells",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "vSiPTgWIPTPTQIaI",
          "name": "+2 Status to All Saves vs. Occult",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "VnvkdDxkW7wfBMjT",
          "name": "Diplomatic Solution",
          "kind": "passive",
          "description": "Trigger The dragon rolls initiative\nEffect The dragon affects all enemies it can see within 60-foot emanation with Calm heightened to half the dragon's level rounded up (check (will, dc:42)). The dragon doesn't need to Sustain this effect, but if the dragon takes any hostile action against those affected, it breaks the effect for all creatures.",
          "traits": [
            "emotion",
            "incapacitation",
            "mental",
            "occult"
          ]
        },
        {
          "id": "XZUptOpkSx0PYtkI",
          "name": "Distracting Whisper",
          "kind": "reaction",
          "description": "Trigger The dragon is targeted with an attack\nEffect A mysterious voice whispers something disconcerting in the triggering creature's ear, inflicting a –2 circumstance penalty to the triggering attack.\nEffect: Distracting Whisper",
          "traits": [
            "mental",
            "occult"
          ]
        },
        {
          "id": "WdFNthO0BdxIqruL",
          "name": "Cogitation Breath",
          "kind": "action",
          "description": "The dragon unleashes a befuddling miasma, dealing 19d6 mental damage in an 80-foot type:cone (check (will, dc:42, basic) save). A creature that fails its save is Stupefied 1 (Stupefied 2 on a critical failure) for 1 minute. The dragon can't use Cogitation Breath again for 1d4.",
          "traits": [
            "mental",
            "occult"
          ]
        },
        {
          "id": "foIbgbTavh92IEGM",
          "name": "Draconic Frenzy",
          "kind": "action",
          "description": "The dragon makes two claw Strikes and one tail Strike in any order.",
          "traits": []
        },
        {
          "id": "gnFWINeBp8o39lnC",
          "name": "Draconic Momentum",
          "kind": "passive",
          "description": "The dragon recharges their Cogitation Breath whenever they score a critical hit with a Strike.",
          "traits": []
        },
        {
          "id": "EZmRWrf1EQnbLdow",
          "name": "Steal Knowledge",
          "kind": "action",
          "description": "The dragon plucks a fragment of knowledge from the mind of a creature within 60 feet, choosing a skill to affect. The creature must attempt a check (will, dc:42) save.\nSuccess The creature is unaffected.\nFailure For the next minute, the creature takes a –1 status penalty to checks using that skill, and the dragon gets a +1 status bonus to using that skill.\nCritical Failure As failure, but the penalty is –2 and the bonus is +2.",
          "traits": [
            "concentrate",
            "mental",
            "occult"
          ]
        },
        {
          "id": "MuGx1WSbRysKWzyR",
          "name": "Thought Whispers",
          "kind": "action",
          "description": "Frequency once per minute\nEffect The dragon sends their mind out to seek others' thoughts, affecting all creatures within 80 feet with mind reading (check (will, dc:42)).",
          "traits": [
            "mental",
            "occult"
          ]
        },
        {
          "id": "dWk0sE2yMPmzHdY2",
          "name": "Unveil Secret",
          "kind": "action",
          "description": "The dragon delves into the mind of a creature within 60 feet, learning something they'd find embarrassing or shameful unless they succeed at a check (will, dc:42) save. The target becomes Frightened 1 and cannot reduce their frightened condition for 1 minute or until the dragon reveals the secret. As a reaction when the affected creature attempts a check, the dragon can reveal their secret to discomfit them, requiring them to roll twice and take the lower result; this is a misfortune effect.",
          "traits": [
            "fear",
            "mental",
            "occult"
          ]
        }
      ],
