      "attacks": [
        {
          "id": "vnSkYAeedjCkt32H",
          "name": "Jaws",
          "bonus": 40,
          "damage": "3d12+24 piercing; 3d6 spirit",
          "traits": [
            "magical",
            "reach-20"
          ]
        },
        {
          "id": "7ffWaGIz0qiXo3RS",
          "name": "Claw",
          "bonus": 38,
          "damage": "3d8+24 slashing; 3d6 spirit",
          "traits": [
            "agile",
            "magical",
            "reach-15"
          ]
        },
        {
          "id": "yC6jZlwTh2jrLSqI",
          "name": "Tail",
          "bonus": 38,
          "damage": "3d10+24 bludgeoning; 3d6 spirit",
          "traits": [
            "magical",
            "reach-25"
          ]
        }
      ],
      "actions": [
        {
          "id": "UnlPuqvn2RpVkX8h",
          "name": "Binding Oath",
          "kind": "passive",
          "description": "The dragon forges a bond with a willing creature over an hour-long ceremony, making them a bonded companion. The dragon can always sense their distance from the companion and if they're moving closer or farther away. A bonded companion automatically critically succeeds on basic saving throws against the oath dragon's abilities and spells. This link is permanent and neither can form a new link until one member dies. If the dragon or the bonded companion dies, the survivor learns the identity of the killer, but the shock leaves the survivor Stupefied 2 for 24 hours and prevents forming a new link for 1 month.\nEffect: Binding Oath",
          "traits": [
            "divine",
            "linguistic",
            "mental"
          ]
        },
        {
          "id": "NtDJUhXysuYsb2uD",
          "name": "+2 Status to All Saves vs. Emotion",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "2oqZY3ZldsOaIRzo",
          "name": "Heartening Aura",
          "kind": "passive",
          "description": "50 feet. All allies in the aura gain a +2 status bonus to attack and damage rolls. The dragon's bonded companion also gains fast healing 20.",
          "traits": [
            "aura",
            "emotion",
            "mental"
          ]
        },
        {
          "id": "fxo4S7G5IiyDGPHf",
          "name": "Shielding Wing",
          "kind": "reaction",
          "description": "Trigger The oath dragon or a bonded companion within 15 feet is targeted with an attack\nEffect The dragon raises its wing to protect itself or the bonded companion, providing a +2 circumstance bonus to AC against the triggering attack. If the dragon is flying, it descends 10 feet after the attack is complete.\nEffect: Shielding Wing",
          "traits": []
        },
        {
          "id": "0YoCRNabKraDJhuz",
          "name": "Castigating Breath",
          "kind": "action",
          "description": "The dragon unleashes a pronouncement that strikes at the soul of its enemies, dealing 15d10 spirit damage in a 60-foot type:cone (check (will, dc:45, basic, options:area-effect,item:defense:basic) save). The dragon can't use Castigating Breath for 1d4.",
          "traits": [
            "divine",
            "spirit"
          ]
        },
        {
          "id": "V3Cb3P8BLdSaE7Ff",
          "name": "Draconic Frenzy",
          "kind": "action",
          "description": "The dragon makes two claw Strikes and one tail Strike in any order.",
          "traits": []
        },
        {
          "id": "KDIAxNFuExWoTyPP",
          "name": "Draconic Momentum",
          "kind": "passive",
          "description": "Whenever they score a critical hit with a Strike, the dragon recharges their Castigating Breath.",
          "traits": []
        },
        {
          "id": "2Za0UG22DSQIkX88",
          "name": "Dread Promise",
          "kind": "action",
          "description": "The dragon's roar shakes the resolve of all those who oppose them. The roar can be heard up to 1 mile away under the open sky. Any enemy who hears it is cowed by the dragon's resolve and must attempt a check (will, dc:45) save.\nCritical Success The creature is unaffected and becomes temporarily immune for 1 hour.\nSuccess The creature becomes Frightened 2.\nFailure The creature becomes Frightened 3 and is Immobilized for as long as it's frightened.\nCritical Failure The creature becomes Frightened 4 and is Fleeing for as long as it's frightened.",
          "traits": [
            "auditory",
            "emotion",
            "fear",
            "mental"
          ]
        },
        {
          "id": "z6T84UanZ74jXYIW",
          "name": "Inspiring Word",
          "kind": "action",
          "description": "All allies within the dragon's heartening aura become Quickened for 1 round. Allies can use this extra action to Raise a Shield, Step, Stride, or Strike.",
          "traits": [
            "auditory",
            "divine",
            "emotion",
            "mental"
          ]
        },
        {
          "id": "5itOh2MJzI6seuWf",
          "name": "Oathbreaker's Curse",
          "kind": "passive",
          "description": "If a bonded companion willingly breaks their oath, they retain the benefit of being a bonded companion but are immediately cursed with no initial saving throw. The cursed creature can attempt saving throws as noted to prevent the curse from worsening.\nSaving Throw check (will, dc:50)\nEffect The cursed creature is Doomed 1 and can't reduce their doomed value below 1 while they're cursed. The first time the cursed creature encounters the oath dragon each day, they must attempt a saving throw. In addition, each time the creature critically fails a Strike or spell attack against the oath dragon, they must attempt a saving throw. On a failure, their doomed value increases by 1, 2 on a critical failure, to a maximum of Doomed 3.",
          "traits": [
            "curse",
            "death",
            "divine"
          ]
        },
        {
          "id": "5z6xCx0dW4XvqYDN",
          "name": "Pull 10 feet",
          "kind": "action",
          "description": "",
          "traits": []
        },
        {
          "id": "XBIGgIOOW7lMHfXX",
          "name": "Push 20 feet",
          "kind": "action",
          "description": "",
          "traits": []
        }
      ],
